/* =========================================================
   NILI'S KITCHEN AI - INGREDIENT ENGINE v3.0
========================================================= */
(function(){
  const baseIngredients = Array.isArray(window.INGREDIENTS) ? window.INGREDIENTS : [];
  const CUSTOM_KEY = "nili_custom_ingredients_v1";

  function normalizeText(value){
    return String(value || "")
      .trim()
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/ı/g,"i")
      .replace(/[^a-z0-9а-яёء-يğüşöçıİĞÜŞÖÇ\s_-]/gi," ")
      .replace(/\s+/g," ")
      .trim();
  }

  function slugify(value){
    return normalizeText(value)
      .replace(/[^a-z0-9а-яёء-ي]+/gi,"_")
      .replace(/^_+|_+$/g,"") || "ingredient";
  }

  function titleCase(value){
    return String(value || "")
      .replace(/_/g," ")
      .replace(/\w\S*/g, txt => txt.charAt(0).toUpperCase() + txt.slice(1).toLowerCase());
  }

  function loadCustomIngredients(){
    try{
      const raw = localStorage.getItem(CUSTOM_KEY);
      const list = raw ? JSON.parse(raw) : [];
      return Array.isArray(list) ? list : [];
    }catch(err){
      return [];
    }
  }

  function saveCustomIngredients(list){
    localStorage.setItem(CUSTOM_KEY, JSON.stringify(Array.isArray(list) ? list : []));
  }

  function allIngredients(){
    return [...baseIngredients, ...loadCustomIngredients()];
  }

  const aliasMap = {};

  function registerIngredient(item){
    if(!item || !item.id) return;
    const names = [
      item.id,
      item.name && item.name.en,
      item.name && item.name.tr,
      item.name && item.name.ru,
      item.name && item.name.ar,
      item.name && item.name.es,
      item.name && item.name.pt,
      item.name && item.name.fr,
      ...(Array.isArray(item.aliases) ? item.aliases : [])
    ];
    names.filter(Boolean).forEach(name => {
      const key = normalizeText(name);
      if(key) aliasMap[key] = item.id;
    });
  }

  baseIngredients.forEach(registerIngredient);
  loadCustomIngredients().forEach(registerIngredient);

  function findIngredient(input){
    const key = normalizeText(input);
    if(!key) return null;
    const id = aliasMap[key];
    if(id){
      return allIngredients().find(item => item.id === id) || null;
    }
    return allIngredients().find(item => {
      if(normalizeText(item.id) === key) return true;
      if(item.name && Object.values(item.name).some(name => normalizeText(name) === key)) return true;
      if(Array.isArray(item.aliases) && item.aliases.some(alias => normalizeText(alias) === key)) return true;
      return false;
    }) || null;
  }

  const CATEGORY_RULES = [
    {category:"vegetables", subcategory:"tomatoes", words:["tomato","domates","pomidor"]},
    {category:"vegetables", subcategory:"onion_family", words:["onion","garlic","leek","sogan","sarmisak","sarımsak"]},
    {category:"vegetables", subcategory:"peppers", words:["pepper","biber","chili"]},
    {category:"fruits", subcategory:"berries", words:["berry","berries","cilek","çilek"]},
    {category:"meat", subcategory:"chicken", words:["chicken","tavuk"]},
    {category:"meat", subcategory:"beef", words:["beef","dana","steak"]},
    {category:"seafood", subcategory:"fish", words:["fish","balik","balık","salmon","tuna","shrimp"]},
    {category:"dairy_eggs", subcategory:"cheese", words:["cheese","peynir","milk","egg"]},
    {category:"grains_bakery", subcategory:"pasta", words:["pasta","makarna","noodle","rice","bread"]},
    {category:"legumes", subcategory:"beans", words:["bean","lentil","chickpea","fasulye","mercimek"]}
  ];

  function guessCategory(input){
    const query = normalizeText(input);
    for(const rule of CATEGORY_RULES){
      if(rule.words.some(word => query.includes(normalizeText(word)))){
        return {category:rule.category, subcategory:rule.subcategory, confidence:0.78};
      }
    }
    return {category:"other", subcategory:"user_added", confidence:0.35};
  }

  function addCustomIngredient(input, options={}){
    const raw = String(input || "").trim();
    if(!raw) return null;

    const existing = findIngredient(raw);
    if(existing) return {...existing, matched:true, source:existing.source || "database"};

    const guess = options.category && options.subcategory
      ? {category:options.category, subcategory:options.subcategory, confidence:1}
      : guessCategory(raw);

    const id = options.id || slugify(raw);

    const custom = {
      id,
      category:guess.category,
      subcategory:guess.subcategory,
      name:{
        en:options.en || titleCase(raw),
        tr:options.tr || raw,
        ru:options.ru || titleCase(raw),
        ar:options.ar || titleCase(raw),
        es:options.es || titleCase(raw),
        pt:options.pt || titleCase(raw),
        fr:options.fr || titleCase(raw)
      },
      aliases:Array.from(new Set([raw, normalizeText(raw), id.replace(/_/g," ")])),
      source:"user_added",
      approved:false,
      confidence:guess.confidence,
      createdAt:new Date().toISOString()
    };

    const customList = loadCustomIngredients();
    if(!customList.find(item => item.id === id)){
      customList.push(custom);
      saveCustomIngredients(customList);
      registerIngredient(custom);
    }
    return custom;
  }

  function resolveIngredient(input){
    const found = findIngredient(input);
    if(found) return {...found, matched:true, source:found.source || "database", confidence:found.confidence || 1};
    return {...addCustomIngredient(input), matched:false};
  }

  function resolveIngredients(inputs){
    const list = Array.isArray(inputs) ? inputs : String(inputs || "").split(",");
    const seen = new Set();
    return list
      .map(item => resolveIngredient(item))
      .filter(Boolean)
      .filter(item => {
        if(seen.has(item.id)) return false;
        seen.add(item.id);
        return true;
      });
  }

  function getCategoryTree(){
    const tree = {};
    allIngredients().forEach(item => {
      if(!tree[item.category]) tree[item.category] = {};
      if(!tree[item.category][item.subcategory]) tree[item.category][item.subcategory] = [];
      tree[item.category][item.subcategory].push(item.id);
    });
    return tree;
  }

  function getIngredientsByCategory(categoryId, subcategoryId){
    return allIngredients().filter(item =>
      (!categoryId || item.category === categoryId) &&
      (!subcategoryId || item.subcategory === subcategoryId)
    );
  }

  window.NilisIngredients = {
    ingredients:Object.fromEntries(baseIngredients.map(item => [item.id, item])),
    aliases:aliasMap,
    normalizeText,
    slugify,
    allIngredients,
    findIngredient,
    guessCategory,
    addCustomIngredient,
    resolveIngredient,
    resolveIngredients,
    getCategoryTree,
    getIngredientsByCategory,
    loadCustomIngredients,
    saveCustomIngredients
  };
})();
